tool_input.command:
cat > tests/LocaleController.test.ts << 'EOF'
import { beforeAll, describe, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'

describe('locale', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('rejects an invalid locale', async () => {
    await http.post('/locale', { locale: 'fr' }).assertStatus(422)
  })

  it('accepts valid locales', async () => {
    await http.post('/locale', { locale: 'en' }).assertStatus(302)
    await http.post('/locale', { locale: 'ja' }).assertStatus(302)
  })
})
EOF
